class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;
        vector<int> temp(n);
        for (int i = 0; i < n; i++) {
            temp[(i + k) % n] = nums[i];
        }
        nums = temp;
    }
};

#include <algorithm>

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;
        // Reverse first n-k elements
        std::reverse(nums.begin(), nums.begin() + (n - k));
        // Reverse last k elements
        std::reverse(nums.begin() + (n - k), nums.end());
        // Reverse whole array
        std::reverse(nums.begin(), nums.end());
    }
};

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;
        int count = 0;
        for (int start = 0; count < n; start++) {
            int current = start;
            int prev = nums[start];
            do {
                int next = (current + k) % n;
                std::swap(prev, nums[next]);
                current = next;
                count++;
            } while (current != start);
        }
    }
};

#include <algorithm>

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;
        // Convert right rotation by k into left rotation by n-k
        std::rotate(nums.begin(), nums.begin() + (n - k), nums.end());
    }
};
